/**
 * TypeScript types for the Adaptive Manifest Protocol (AMP) v1.0.
 * Generated by hand from amp.schema.json. Keep in sync.
 */

export type AmpLanguage = "typescript" | "python" | "go";
export type AmpTransport = "stdio" | "tcp" | "external";
export type AmpReasoningEffort = "minimal" | "low" | "medium" | "high";
export type AmpLogLevel = "error" | "warning" | "info" | "debug" | "all" | "none";

export interface AmpManifest {
  ampVersion: "1.0";
  agent: AmpAgent;
  runtime: AmpRuntime;
  extensions?: AmpExtensions;
  communication?: AmpCommunication;
  build?: AmpBuild;
  deployment?: AmpDeployment;
}

export interface AmpAgent {
  name: string;
  displayName?: string;
  version?: string;
  description?: string;
  author?: string;
  license?: string;
  language: AmpLanguage;
  tags?: string[];
}

export interface AmpRuntime {
  copilotSdk: AmpCopilotSdkConfig;
  model?: AmpModelConfig;
  provider?: AmpProviderConfig;
  workingDirectory?: string;
  streaming?: boolean;
  includeSubAgentStreamingEvents?: boolean;
  infiniteSessions?: boolean;
  ui?: { elicitation?: boolean };
}

export interface AmpCopilotSdkConfig {
  transport?: AmpTransport;
  cliUrl?: string;
  cliPath?: string;
  useLoggedInUser?: boolean;
  gitHubTokenEnv?: string;
  logLevel?: AmpLogLevel;
  sessionIdleTimeoutSec?: number;
}

export interface AmpModelConfig {
  name?: string;
  reasoningEffort?: AmpReasoningEffort;
  capabilitiesOverride?: Record<string, unknown>;
}

export interface AmpProviderConfig {
  type?: "azure" | "anthropic" | "openai" | "ollama" | "gemini";
  [key: string]: unknown;
}

export interface AmpExtensions {
  tools?: AmpTool[];
  availableTools?: string[];
  excludedTools?: string[];
  mcpServers?: AmpMcpServer[];
  customAgents?: AmpCustomAgent[];
  defaultAgent?: { name?: string; tools?: string[]; excludedTools?: string[] };
  agent?: string;
  hooks?: AmpHooks;
  permissions?: AmpPermissions;
  skills?: AmpSkillsConfig;
  systemMessage?: AmpSystemMessage;
  sessionFs?: AmpSessionFs;
  lifecycle?: { handler?: string };
  userInput?: { handler?: string };
  commands?: AmpCommand[];
}

export interface AmpTool {
  name: string;
  description: string;
  paramsSchema?: string | Record<string, unknown>;
  handler?: string;
  skipPermission?: boolean;
  overridesBuiltIn?: boolean;
  stub?: AmpToolStub;
}

export interface AmpToolStub {
  kind: "echo" | "static" | "memoryRead" | "memoryWrite" | "memoryList";
  value?: unknown;
}

export interface AmpMcpServer {
  name: string;
  type: "stdio" | "http" | "sse";
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  url?: string;
  headers?: Record<string, string>;
  tools?: string[];
}

export interface AmpCustomAgent {
  name: string;
  description: string;
  systemPrompt?: string;
  model?: string;
  reasoningEffort?: AmpReasoningEffort;
  tools?: string[];
  excludedTools?: string[];
  mcpServers?: string[];
}

export interface AmpHooks {
  preToolUse?: string;
  postToolUse?: string;
  userPromptSubmitted?: string;
  sessionStart?: string;
  sessionEnd?: string;
  errorOccurred?: string;
}

export interface AmpPermissions {
  mode?: "custom" | "approveAll" | "denyAll" | "allowList";
  handler?: string;
  autoApprove?: { tool: string; argsContains?: string }[];
}

export interface AmpSkillsConfig {
  directories?: string[];
  disabled?: string[];
  inline?: AmpInlineSkill[];
}

export interface AmpInlineSkill {
  name: string;
  description: string;
  instructions: string;
}

export type AmpSystemMessageMode = "customize" | "append" | "replace";

export interface AmpSystemMessage {
  mode?: AmpSystemMessageMode;
  content?: string;
  sections?: Record<string, string | { append?: string; prepend?: string; replace?: string }>;
}

export interface AmpSessionFs {
  provider?: "memory" | "real" | "custom";
  handler?: string;
}

export interface AmpCommand {
  name: string;
  description: string;
  argsHint?: string;
  handler?: string;
}

export interface AmpCommunication {
  standard?: "amp-acs-1.0";
  id?: string;
  broadcast?: { channels?: string[]; transport?: "stdout-jsonl" | "websocket" | "file" | "none" };
  inbox?: { enabled?: boolean; path?: string };
  handoff?: { name: string; description?: string; transport?: "stdio" | "http" | "inbox"; endpoint?: string }[];
}

export interface AmpBuild {
  outputDir?: string;
  entrypoint?: string;
  bundler?: "none" | "esbuild" | "tsc" | "tsx";
  packageManager?: "npm" | "pnpm" | "yarn" | "uv" | "pip" | "go";
}

export interface AmpDeployment {
  target?: "standalone" | "container" | "wasm" | "serverless";
  scripts?: Record<string, string>;
  env?: Record<string, string>;
}
